def split_row(line: str):
    """Split one CSV line into fields.

    Commas inside double-quoted fields are literal, and two consecutive
    double quotes inside a quoted field represent one literal quote.
    """
    fields = []
    field = []
    in_quotes = False
    index = 0

    while index < len(line):
        char = line[index]

        if char == '"':
            if in_quotes:
                if index + 1 < len(line) and line[index + 1] == '"':
                    field.append('"')
                    index += 1
                else:
                    in_quotes = False
            else:
                in_quotes = True
        elif char == ',' and not in_quotes:
            fields.append(''.join(field))
            field = []
        else:
            field.append(char)

        index += 1

    fields.append(''.join(field))
    return fields

